def field(key,title,typ,description,default=None,**kw):
 d={'title':title,'type':typ,'description':description}
 if default is not None:d['default']=default
 if typ=='string':d['editor']='textfield'
 if typ=='array':d.update(editor='stringList',items={'type':'string'})
 if typ=='object':d['editor']='json'
 d.update(kw);p[key]=d
