texts={'adKey':'SHA-1 of advertiser user ID, tweet ID, line-item ID and served country.','adId':'Repository ad identifier, or the tweet ID when no ad identifier is disclosed.','adIdSource':'repository or tweet_id_fallback.','tweetId':'Post ID preserved exactly as a string, never floating point.','lineItemId':'Disclosed advertising line-item ID.','accountId':'Disclosed advertising account ID; not necessarily the public user ID.','adName':'Derived name, never represented as a disclosed X campaign title.','adNameSource':'Name derivation: UTM campaign/content, creative headline, or identity.','adUrl':'Public post link.','adCreatedAt':'UTC post creation from Snowflake arithmetic, not campaign delivery start.','adCreatedAtSource':'derived_tweet_snowflake or invalid_or_pre_snowflake_id.','deliveryStart':'Disclosed delivery start, otherwise null; query window is not substituted.','deliveryStartSource':'Provenance for deliveryStart.','deliveryEnd':'Disclosed delivery end, otherwise null.','deliveryEndSource':'Provenance for deliveryEnd.','daysActiveSource':'Actual disclosed-date derivation or reason duration cannot be inferred.','firstSeenAt':'First observed timestamp; monitor state retains it across runs.','lastSeenAt':'Last observed timestamp, not the removal report timestamp.','scrapedAt':'UTC observation/run timestamp.','country':'ISO alpha-2 country where this ad was served.','countryName':'ISO regional display name.','countryNameSource':'ISO/Intl derived country name or unknown.','targetedLocationsStatus':'Whether geo-targeting was actually disclosed.','targetingStatus':'Whether targeting was actually disclosed.','targetingSummary':'Human-readable targeting string suitable for CSV.','impressionsStatus':'Repository count or aggregation/unknown reason.','reachStatus':'Repository reach or non-additive multi-chunk reason.','fundingStatus':'Disclosed funding coverage; missing nested fields carry availability reasons.','approvalStatus':'Source approval status preserved as disclosed.','approvalStatusSource':'Repository or not_disclosed.','isHaltedSource':'Explicit repository flag/status or reason unavailable.','changeStatus':'NEW, CHANGED, UNCHANGED or REMOVED.','schemaVersion':'Version of normalized output contract.'}
