creative={}
for k,d in {'text':'Disclosed/enriched public post text.','textSource':'repository, public_oembed, official_api or unavailable reason.','authorName':'Public post author display name.','authorNameSource':'Author-name provenance.','mediaType':'Disclosed asset type; unknown stays unknown.','mediaTypeSource':'Media-type provenance.','assetCountSource':'Observed asset-count provenance; missing assets never imply zero.','landingUrl':'Disclosed/resolved destination URL.','landingUrlStatus':'repository/resolved/unavailable/error reason.','landingDomain':'Host derived from landingUrl.','landingDomainSource':'Domain derivation/provenance.','enrichmentStatus':'ok, not_attempted, deleted_or_unavailable, protected, rate_limited or error.'}.items():creative[k]=prop('string',d,k in ['text','authorName','landingUrl','landingDomain'])
